import{H as e,V as t,et as n,j as r}from"./chunks/framework.CW0zsFMp.js";import{_a as i,ga as a,va as o}from"./chunks/assets.BxHYjuf8.js";var s=JSON.parse(`{"title":"存储引擎","description":"","frontmatter":{},"headers":[],"relativePath":"mysql/storage-engines.md","filePath":"mysql/storage-engines.md"}`),c={name:`mysql/storage-engines.md`};function l(r,s,c,l,u,d){return n(),t(`div`,null,[...s[0]||=[e(`<h1 id="存储引擎" tabindex="-1">存储引擎 <a class="header-anchor" href="#存储引擎" aria-label="Permalink to “存储引擎”">​</a></h1><h2 id="_1-mysql体系结构" tabindex="-1">1.MySQL体系结构 <a class="header-anchor" href="#_1-mysql体系结构" aria-label="Permalink to “1.MySQL体系结构”">​</a></h2><p><img src="`+o+`" alt="c36089af5b234597b17622df24572e0dpng" width="1715" height="785"></p><p><img src="`+i+`" alt="8da74f4fb6f5489dacad61614038b515png" width="1622" height="646"></p><p>存储引擎就是存储数据、建立索引、更新/查询数据等技术的实现方式。存储引擎是基于表而不是基于库的，所以存储引擎也可以被称为表引擎。</p><ul><li>默认存储引擎是InnoDB</li></ul><h2 id="_2-相关语句" tabindex="-1">2.相关语句 <a class="header-anchor" href="#_2-相关语句" aria-label="Permalink to “2.相关语句”">​</a></h2><p>创建表时指定存储引擎</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> 表名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) ENGINE</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">INNODB;</span></span></code></pre></div><p>查看当前数据库支持的存储引擎</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show engines;</span></span></code></pre></div><h2 id="_3-innodb" tabindex="-1">3.InnoDB <a class="header-anchor" href="#_3-innodb" aria-label="Permalink to “3.InnoDB”">​</a></h2><p>InnoDB 是一种兼顾高可靠性和高性能的通用存储引擎，在 MySQL 5.5 之后，InnoDB 是默认的 MySQL 引擎。</p><h3 id="_3-1-特点" tabindex="-1">3.1 特点 <a class="header-anchor" href="#_3-1-特点" aria-label="Permalink to “3.1 特点”">​</a></h3><ul><li><p>DML 操作遵循 ACID 模型，支持<strong>事务</strong></p></li><li><p><strong>行级锁</strong>，提高并发访问性能</p></li><li><p>支持<strong>外键</strong>约束，保证数据的完整性和正确性</p></li></ul><h3 id="_3-2-文件" tabindex="-1">3.2 文件 <a class="header-anchor" href="#_3-2-文件" aria-label="Permalink to “3.2 文件”">​</a></h3><p><code>xxx.ibd</code>：xxx代表表名，InnoDB 引擎的每张表都会对应这样一个表空间文件，存储该表的表结构（frm、sdi）、数据和索引。 参数：innodb_file_per_table，决定多张表共享一个表空间（OFF）还是每张表对应一个表空间（ON）</p><p>查看MySQL变量</p><div class="language-SQL"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">SQL</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">show variables </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">like</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;innodb_file_per_table&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>从idb文件提取表结构数据（在cmd执行）</p><div class="language-PowerShell"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">PowerShell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ibd2sdi 表名.ibd</span></span></code></pre></div><h3 id="_3-3-innodb-逻辑存储结构" tabindex="-1">3.3 InnoDB 逻辑存储结构 <a class="header-anchor" href="#_3-3-innodb-逻辑存储结构" aria-label="Permalink to “3.3 InnoDB 逻辑存储结构”">​</a></h3><p><img src="`+a+`" alt="d5755dfc500447d39096f12fc1231ae5png" width="1537" height="647"></p><h2 id="_4-myisam" tabindex="-1">4.MyISAM <a class="header-anchor" href="#_4-myisam" aria-label="Permalink to “4.MyISAM”">​</a></h2><p>MyISAM 是 MySQL 早期的默认存储引擎。</p><h3 id="_4-1-特点" tabindex="-1">4.1 特点 <a class="header-anchor" href="#_4-1-特点" aria-label="Permalink to “4.1 特点”">​</a></h3><ul><li><p>不支持事务，不支持外键</p></li><li><p>支持表锁，不支持行锁</p></li><li><p>访问速度快</p></li></ul><h3 id="_4-2-文件" tabindex="-1">4.2 文件 <a class="header-anchor" href="#_4-2-文件" aria-label="Permalink to “4.2 文件”">​</a></h3><ul><li><p><code>表名.sdi</code>：存储表结构信息</p></li><li><p><code>表名.MYD</code>：存储数据</p></li><li><p><code>表名.MYI</code>：存储索引</p></li></ul><h2 id="_5-memory" tabindex="-1">5.Memory <a class="header-anchor" href="#_5-memory" aria-label="Permalink to “5.Memory”">​</a></h2><p>Memory 引擎的表数据是存储在内存中的，受硬件问题、断电问题的影响，只能将这些表作为临时表或缓存使用。</p><h3 id="_5-1-特点" tabindex="-1">5.1 特点 <a class="header-anchor" href="#_5-1-特点" aria-label="Permalink to “5.1 特点”">​</a></h3><ul><li><p>存放在内存中，速度快</p></li><li><p>hash索引（默认）</p></li></ul><h3 id="_5-2-文件" tabindex="-1">5.2 文件 <a class="header-anchor" href="#_5-2-文件" aria-label="Permalink to “5.2 文件”">​</a></h3><ul><li><code>表名.sdi</code>：存储表结构信息</li></ul><h2 id="_6-存储引擎的比较" tabindex="-1">6.存储引擎的比较 <a class="header-anchor" href="#_6-存储引擎的比较" aria-label="Permalink to “6.存储引擎的比较”">​</a></h2><table tabindex="0"><thead><tr><th>特点</th><th>InnoDB</th><th>MyISAM</th><th>Memory</th></tr></thead><tbody><tr><td>存储限制</td><td>64TB</td><td>有</td><td>有</td></tr><tr><td>事务安全</td><td><strong>支持</strong></td><td>-</td><td>-</td></tr><tr><td>锁机制</td><td><strong>行锁</strong></td><td>表锁</td><td>表锁</td></tr><tr><td>B+tree索引</td><td>支持</td><td>支持</td><td>支持</td></tr><tr><td>Hash索引</td><td>-</td><td>-</td><td>支持</td></tr><tr><td>全文索引</td><td>支持（5.6版本之后）</td><td>支持</td><td>-</td></tr><tr><td>空间使用</td><td>高</td><td>低</td><td>N/A</td></tr><tr><td>内存使用</td><td>高</td><td>低</td><td>中等</td></tr><tr><td>批量插入速度</td><td>低</td><td>高</td><td>高</td></tr><tr><td>支持外键</td><td><strong>支持</strong></td><td>-</td><td>-</td></tr></tbody></table><h2 id="_7-存储引擎的选择" tabindex="-1">7.存储引擎的选择 <a class="header-anchor" href="#_7-存储引擎的选择" aria-label="Permalink to “7.存储引擎的选择”">​</a></h2><p>在选择存储引擎时，应该根据应用系统的特点选择合适的存储引擎。对于复杂的应用系统，还可以根据实际情况选择多种存储引擎进行组合。</p><ul><li><p>InnoDB: 如果应用对事物的完整性有比较高的要求，在并发条件下要求数据的一致性，数据操作除了插入和查询之外，还包含很多的更新、删除操作，则 InnoDB 是比较合适的选择</p></li><li><p>MyISAM: 如果应用是以读操作和插入操作为主，只有很少的更新和删除操作，并且对事务的完整性、并发性要求不高，那这个存储引擎是非常合适的。</p></li><li><p>Memory: 将所有数据保存在内存中，访问速度快，通常用于临时表及缓存。Memory 的缺陷是对表的大小有限制，太大的表无法缓存在内存中，而且无法保障数据的安全性</p></li></ul><p>电商中的足迹和评论适合使用 MyISAM 引擎，缓存适合使用 Memory 引擎。</p>`,41)]])}var u=r(c,[[`render`,l]]);export{s as __pageData,u as default};